{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "Weighs model-based and model-free Q-values to compute net stage-1 values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice stickiness",
      "description": "Adds a perseveration bonus to the stage-1 logits for the action chosen in the previous trial.",
      "params": [
        {
          "name": "pers",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "rep_1 = np.zeros(2)\nif last_action_1 != -1:\n    rep_1[last_action_1] = 1\nlogits_1 = beta_1 * q_stage1_net + pers * rep_1",
      "expressible_in_slots": true
    },
    {
      "name": "subjective_penalty_zero",
      "title": "Subjective penalty for zero reward",
      "description": "Replaces a 0 reward with a subjective negative penalty parameter to accelerate avoidance of unrewarding options.",
      "params": [
        {
          "name": "penalty_zero",
          "bounds": [0, 2]
        }
      ],
      "evidence": "subj_reward = 1.0 if reward[trial] == 1 else -penalty_zero\ndelta_stage2 = subj_reward - q_stage2_mf[state_idx, action_2[trial]]",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility trace",
      "description": "Updates the stage-1 model-free Q-value of the chosen action using the stage-2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value decay/forgetting",
      "description": "Multiplies all unchosen Q-values at both stages by a decay parameter at the end of each trial.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_action_1] *= decay\nunchosen_action_2 = 1 - action_2[trial]\nq_stage2_mf[state_idx, unchosen_action_2] *= decay\nother_state = 1 - state_idx\nq_stage2_mf[other_state, 0] *= decay\nq_stage2_mf[other_state, 1] *= decay",
      "expressible_in_slots": true
    }
  ]
}
